import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '근태 담당자';
const USE_VALUES = ['사용', '미사용'];
const DATE_PATTERN = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const SELECT_COLUMNS = `attendance_criteria_id AS "attendanceCriteriaId",
  criteria_name AS "criteriaName",
  basic_attendance_criteria AS "basicAttendanceCriteria",
  work_time_criteria AS "workTimeCriteria",
  overtime_criteria AS "overtimeCriteria",
  use_yn AS "useYn",
  apply_start_date AS "applyStartDate"`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'ATTENDANCE_CRITERIA_INVALID', message);
}

function optionalText(data: Record<string, unknown>, key: string, label: string): string | null | undefined {
  if (!(key in data)) {
    return undefined;
  }
  const value = data[key];
  if (value === null || value === undefined || value === '') {
    return null;
  }
  if (typeof value !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

function criteriaNameOf(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid('기준명은 필수입니다.');
  }
  if (value.length > 200) {
    throw invalid('기준명은 200자 이내로 입력해 주세요.');
  }
  return value.trim();
}

function useYnOf(value: unknown): string {
  if (typeof value !== 'string' || !USE_VALUES.includes(value)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return value;
}

function applyStartDateOf(value: unknown): string {
  if (typeof value !== 'string' || !DATE_PATTERN.test(value)) {
    throw invalid('적용 시작일은 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return value;
}

function intParam(value: unknown, fallback: number): number {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }
  const n = Number(value);
  if (!Number.isInteger(n)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기는 정수여야 합니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr01701Controller {
  @Get('/attendance-criteria')
  async listAttendanceCriteria(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query) as Record<string, unknown>;
    const page = intParam(query['page'], 0);
    const size = intParam(query['size'], DEFAULT_SIZE);
    if (page < 0 || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);
    const useYn = query['useYn'];
    const params: Record<string, unknown> = { size: pageSize, offset: page * pageSize };
    let where = '';
    if (useYn !== undefined && useYn !== null && useYn !== '') {
      if (typeof useYn !== 'string' || !USE_VALUES.includes(useYn)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 여부는 사용 또는 미사용이어야 합니다.');
      }
      where = 'WHERE use_yn = :useYn';
      params['useYn'] = useYn;
    }
    return transaction(async (db) => {
      const counts = await db.query(
        `SELECT COUNT(*) AS total FROM attendance_criteria ${where}`,
        params,
      );
      const items = await db.query(
        `SELECT ${SELECT_COLUMNS}
         FROM attendance_criteria ${where}
         ORDER BY attendance_criteria_id DESC
         LIMIT :size OFFSET :offset`,
        params,
      );
      return { items, page, size: pageSize, total: Number(counts[0].total) };
    });
  }

  @Post('/attendance-criteria')
  @HttpCode(200)
  async createAttendanceCriteria(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const params = {
      criteriaName: criteriaNameOf(data['criteriaName']),
      basic: optionalText(data, 'basicAttendanceCriteria', '기본 근태 기준') ?? null,
      workTime: optionalText(data, 'workTimeCriteria', '근무시간 기준') ?? null,
      overtime: optionalText(data, 'overtimeCriteria', '시간외근무 기준') ?? null,
      useYn: useYnOf(data['useYn']),
      applyStartDate: applyStartDateOf(data['applyStartDate']),
    };
    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO attendance_criteria
           (criteria_name, basic_attendance_criteria, work_time_criteria, overtime_criteria,
            use_yn, apply_start_date, created_at, updated_at)
         VALUES
           (:criteriaName, :basic, :workTime, :overtime,
            :useYn, CAST(:applyStartDate AS date), now(), now())
         RETURNING attendance_criteria_id AS "attendanceCriteriaId"`,
        params,
      );
      return { attendanceCriteriaId: Number(rows[0].attendanceCriteriaId) };
    });
  }

  @Patch('/attendance-criteria/:attendanceCriteriaId')
  async updateAttendanceCriteria(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['attendanceCriteriaId'];
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const sets: string[] = [];
    const params: Record<string, unknown> = { id };
    if ('criteriaName' in data) {
      sets.push('criteria_name = :criteriaName');
      params['criteriaName'] = criteriaNameOf(data['criteriaName']);
    }
    const basic = optionalText(data, 'basicAttendanceCriteria', '기본 근태 기준');
    if (basic !== undefined) {
      sets.push('basic_attendance_criteria = :basic');
      params['basic'] = basic;
    }
    const workTime = optionalText(data, 'workTimeCriteria', '근무시간 기준');
    if (workTime !== undefined) {
      sets.push('work_time_criteria = :workTime');
      params['workTime'] = workTime;
    }
    const overtime = optionalText(data, 'overtimeCriteria', '시간외근무 기준');
    if (overtime !== undefined) {
      sets.push('overtime_criteria = :overtime');
      params['overtime'] = overtime;
    }
    if ('useYn' in data) {
      sets.push('use_yn = :useYn');
      params['useYn'] = useYnOf(data['useYn']);
    }
    if ('applyStartDate' in data) {
      sets.push('apply_start_date = CAST(:applyStartDate AS date)');
      params['applyStartDate'] = applyStartDateOf(data['applyStartDate']);
    }
    return transaction(async (db) => {
      if (typeof id !== 'string' || !/^\d{1,18}$/.test(id)) {
        throw new ApiError(404, 'ATTENDANCE_CRITERIA_NOT_FOUND', '근태 기준정보를 찾을 수 없습니다.');
      }
      const found = await db.query(
        'SELECT attendance_criteria_id FROM attendance_criteria WHERE attendance_criteria_id = CAST(:id AS bigint)',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_CRITERIA_NOT_FOUND', '근태 기준정보를 찾을 수 없습니다.');
      }
      if (sets.length === 0) {
        throw invalid('수정할 값이 없습니다.');
      }
      const rows = await db.query(
        `UPDATE attendance_criteria
         SET ${sets.join(', ')}, updated_at = now()
         WHERE attendance_criteria_id = CAST(:id AS bigint)
         RETURNING attendance_criteria_id AS "attendanceCriteriaId"`,
        params,
      );
      return { attendanceCriteriaId: Number(rows[0].attendanceCriteriaId) };
    });
  }
}

