import { useState } from 'react';
import { call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Form, Field, TextInput, DateInput, Select, Tiles } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;
const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];

const EMPTY_FORM: Row = {
  criteriaName: '',
  basicAttendanceCriteria: '',
  workTimeCriteria: '',
  overtimeCriteria: '',
  useYn: '사용',
  applyStartDate: '',
};

export default function FnSfr01701Page({ role, notify }: PageProps) {
  const [filterUse, setFilterUse] = useState('');
  const [appliedUse, setAppliedUse] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [mode, setMode] = useState<'none' | 'create' | 'detail' | 'edit'>('none');
  const [selected, setSelected] = useState<Row | null>(null);
  const [form, setForm] = useState<Row>(EMPTY_FORM);

  const list = useData<Page>(
    () => call<Page>('GET', '/attendance-criteria', role, undefined, { useYn: appliedUse, page: pageNo, size: SIZE }),
    [appliedUse, pageNo],
  );
  const counts = useData<[Page, Page]>(
    () => Promise.all([
      call<Page>('GET', '/attendance-criteria', role, undefined, { useYn: '사용', page: 0, size: 1 }),
      call<Page>('GET', '/attendance-criteria', role, undefined, { useYn: '미사용', page: 0, size: 1 }),
    ]),
    [],
  );

  const refresh = () => {
    list.reload();
    counts.reload();
  };
  const close = () => {
    setMode('none');
    setSelected(null);
  };
  const setField = (key: string, value: unknown) => setForm((prev) => ({ ...prev, [key]: value }));

  const openCreate = () => {
    setForm({ ...EMPTY_FORM });
    setMode('create');
  };
  const openDetail = (row: Row) => {
    setSelected(row);
    setMode('detail');
  };
  const openEdit = () => {
    if (!selected) {
      return;
    }
    setForm({
      criteriaName: selected['criteriaName'] ?? '',
      basicAttendanceCriteria: selected['basicAttendanceCriteria'] ?? '',
      workTimeCriteria: selected['workTimeCriteria'] ?? '',
      overtimeCriteria: selected['overtimeCriteria'] ?? '',
      useYn: selected['useYn'] ?? '사용',
      applyStartDate: String(selected['applyStartDate'] ?? '').slice(0, 10),
    });
    setMode('edit');
  };

  const checkForm = () => {
    if (String(form['criteriaName'] ?? '').trim() === '') {
      throw new Error('기준명을 입력해 주세요.');
    }
    if (!form['useYn']) {
      throw new Error('사용 여부를 선택해 주세요.');
    }
    if (!form['applyStartDate']) {
      throw new Error('적용 시작일을 입력해 주세요.');
    }
  };
  const bodyOf = (): Row => ({
    criteriaName: form['criteriaName'],
    basicAttendanceCriteria: form['basicAttendanceCriteria'],
    workTimeCriteria: form['workTimeCriteria'],
    overtimeCriteria: form['overtimeCriteria'],
    useYn: form['useYn'],
    applyStartDate: form['applyStartDate'],
  });

  const submitCreate = async () => {
    checkForm();
    await call('POST', '/attendance-criteria', role, bodyOf());
    notify('근태 기준정보를 등록했습니다.');
    close();
    setPageNo(0);
    refresh();
  };
  const submitEdit = async () => {
    checkForm();
    await call('PATCH', '/attendance-criteria/' + String(selected?.['attendanceCriteriaId']), role, bodyOf());
    notify('근태 기준정보를 수정했습니다.');
    close();
    refresh();
  };
  const submitToggle = async () => {
    const next = selected?.['useYn'] === '사용' ? '미사용' : '사용';
    await call('PATCH', '/attendance-criteria/' + String(selected?.['attendanceCriteriaId']), role, { useYn: next });
    notify('사용 여부를 ' + next + '(으)로 변경했습니다.');
    close();
    refresh();
  };

  const data = list.data;
  const inUse = counts.data ? counts.data[0].total : 0;
  const notInUse = counts.data ? counts.data[1].total : 0;

  const formFields = (
    <>
      <Field label="기준명" required wide>
        <TextInput value={form['criteriaName']} onChange={(v) => setField('criteriaName', v)} />
      </Field>
      <Field label="기본 근태 기준" wide>
        <TextInput multiline value={form['basicAttendanceCriteria']} onChange={(v) => setField('basicAttendanceCriteria', v)} />
      </Field>
      <Field label="근무시간 기준" wide>
        <TextInput multiline value={form['workTimeCriteria']} onChange={(v) => setField('workTimeCriteria', v)} />
      </Field>
      <Field label="시간외근무 기준" wide>
        <TextInput multiline value={form['overtimeCriteria']} onChange={(v) => setField('overtimeCriteria', v)} />
      </Field>
      <Field label="사용 여부" required>
        <Select value={form['useYn']} onChange={(v) => setField('useYn', v)} options={USE_OPTIONS} />
      </Field>
      <Field label="적용 시작일" required>
        <DateInput value={form['applyStartDate']} onChange={(v) => setField('applyStartDate', v)} />
      </Field>
    </>
  );

  return (
    <div className="bento">
      <section className="box span-6">
        <h2>사용 기준</h2>
        <Tiles items={[['사용 중인 기준', inUse]]} />
      </section>
      <section className="box span-6">
        <h2>미사용 기준</h2>
        <Tiles items={[['미사용 기준', notInUse]]} />
      </section>
      <section className="box span-12">
        <h2>근태 기준정보</h2>
        <Filters
          onSearch={() => {
            setPageNo(0);
            setAppliedUse(filterUse);
          }}
          onReset={() => {
            setFilterUse('');
            setAppliedUse('');
            setPageNo(0);
          }}
        >
          <Field label="사용 여부">
            <Select value={filterUse} onChange={setFilterUse} options={USE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={openCreate}>기준정보 등록</button>
        </Band>
        <DataTable
          rows={data?.items ?? []}
          onRowClick={openDetail}
          empty={list.error || '등록된 근태 기준정보가 없습니다.'}
          columns={[
            { key: 'criteriaName', label: '기준명' },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
            { key: 'applyStartDate', label: '적용 시작일', render: (r) => <DateText value={r['applyStartDate']} /> },
          ]}
        />
        <Pager page={data?.page ?? 0} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>

      {mode === 'create' && (
        <Drawer title="근태 기준정보 등록" onClose={close}>
          <Form onSubmit={submitCreate} submit="등록">
            {formFields}
          </Form>
        </Drawer>
      )}
      {mode === 'edit' && selected && (
        <Drawer title="근태 기준정보 수정" onClose={close}>
          <Form onSubmit={submitEdit} submit="저장">
            {formFields}
          </Form>
        </Drawer>
      )}
      {mode === 'detail' && selected && (
        <Drawer title="근태 기준정보 상세" onClose={close}>
          <Pairs
            items={[
              ['기준명', String(selected['criteriaName'] ?? '')],
              ['기본 근태 기준', String(selected['basicAttendanceCriteria'] ?? '')],
              ['근무시간 기준', String(selected['workTimeCriteria'] ?? '')],
              ['시간외근무 기준', String(selected['overtimeCriteria'] ?? '')],
              ['사용 여부', <Badge value={selected['useYn']} />],
              ['적용 시작일', <DateText value={selected['applyStartDate']} />],
            ]}
          />
          <Band>
            <button type="button" onClick={openEdit}>수정</button>
          </Band>
          <Form
            onSubmit={submitToggle}
            submit={selected['useYn'] === '사용' ? '미사용으로 변경' : '사용으로 변경'}
            danger={selected['useYn'] === '사용'}
          />
        </Drawer>
      )}
    </div>
  );
}
